begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('11000000-0000-0000-0000-000000000001'),('11000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.journal_entries(id,title,body,music) values ('21000000-0000-0000-0000-000000000001','Synthetic soundtrack','Private writing','{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","share":false}')$$,'private music saves');
select throws_ok($$update public.journal_entries set music='{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","share":false,"secret":"private"}'$$,'23514',null,'unknown private fields rejected');
select throws_ok($$update public.journal_entries set music='{"provider":"spotify","kind":"track","id":"javascript:alert(1)","share":false}'$$,'23514',null,'unsafe ID rejected');
select throws_ok($$insert into public.public_stories(id,user_id,title,body,music) values ('21000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000001','Public','Public writing','{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC"}')$$,'23514',null,'unapproved music cannot be published via raw API');
select lives_ok($$update public.journal_entries set music=jsonb_set(music,'{share}','true')$$,'explicit source approval');
select lives_ok($$insert into public.public_stories(id,user_id,title,body,music) values ('21000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000001','Public','Public writing','{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC"}')$$,'approved snapshot published');
select throws_ok($$update public.public_stories set music='{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQD"}'$$,'23514',null,'different unapproved track rejected');
select throws_ok($$update public.public_stories set music='{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","share":true}'$$,'23514',null,'public copy cannot contain private fields');
select lives_ok($$update public.journal_entries set music='{"provider":"spotify","kind":"album","id":"4uLU6hMCjMI75M1A2tKUQD","share":false}'$$,'private selection changes independently');
select is((select music->>'kind' from public.public_stories),'track','public snapshot remains unchanged');
select set_config('request.jwt.claims','{"sub":"11000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.journal_entries),0,'B cannot read A music');
select lives_ok($$update public.journal_entries set music=null where id='21000000-0000-0000-0000-000000000001'$$,'B private update matches no row');
select lives_ok($$update public.public_stories set music=null where id='21000000-0000-0000-0000-000000000001'$$,'B public update matches no row');
select is((select music->>'kind' from public.public_stories),'track','B did not change public selection');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select music from public.journal_entries$$,'42501',null,'anonymous private music denied');
select is((select music from public.public_stories),'{"provider":"spotify","kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC"}'::jsonb,'anonymous sees exactly approved public music');
select throws_ok($$update public.public_stories set music=null$$,'42501',null,'anonymous cannot change music');
select throws_ok($$select user_id from public.public_stories$$,'42501',null,'public owner ID remains hidden');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select music->>'kind' from public.journal_entries),'album','B did not change private selection');
select lives_ok($$delete from public.public_stories where id='21000000-0000-0000-0000-000000000001'$$,'author unpublishes');
set local role anon;
select is((select count(id)::int from public.public_stories),0,'unpublish revokes public music access');
reset role;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.journal_entries'::regclass),'private RLS remains forced');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.public_stories'::regclass),'public RLS remains forced');
select * from finish();
rollback;
